import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"2. Constraints","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/arc42/02-constraints.md","filePath":"architecture/arc42/02-constraints.md","lastUpdated":1780254295000}'),s={name:"architecture/arc42/02-constraints.md"};function r(i,e,c,d,l,u){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_2-constraints" tabindex="-1">2. Constraints <a class="header-anchor" href="#_2-constraints" aria-label="Permalink to &quot;2. Constraints&quot;">​</a></h1><h2 id="technical-constraints" tabindex="-1">Technical constraints <a class="header-anchor" href="#technical-constraints" aria-label="Permalink to &quot;Technical constraints&quot;">​</a></h2><ul><li><strong>Desktop daemon is in-process</strong>: <code>soma-daemon</code> ships as a library linked into the <code>@soma/node</code> napi addon and runs inside the Electron main process. There is no separate daemon binary, no Unix-socket IPC, and no HTTP/Axum surface on the desktop side.</li><li><strong>Server backends use Axum + metrics</strong>: <code>somad bot</code>, <code>somad relay</code>, <code>somad rendezvous</code>, <code>somad bff</code> expose <code>GET /healthz</code> and <code>GET /metrics</code>.</li><li><strong>Rust workspace dependency policy</strong>: third-party versions live only in root <code>Cargo.toml</code> under <code>[workspace.dependencies]</code>.</li><li><strong>Desktop JS tooling</strong>: <code>pnpm</code> workspace under <code>desktop/</code>.</li><li><strong>Offline-first networking</strong>: must function on LAN without servers (mDNS) and across networks with optional infra (rendezvous + relay).</li></ul><h2 id="product-constraints" tabindex="-1">Product constraints <a class="header-anchor" href="#product-constraints" aria-label="Permalink to &quot;Product constraints&quot;">​</a></h2><ul><li><strong>No accounts/passwords</strong>: identity is device-based (PeerId); human names are UI-only.</li><li><strong>Bots are explicit members</strong>: VDF/bot peers are not implicit trusted infrastructure; space owners can remove/revoke them.</li><li><strong>Cache-only VDF role</strong>: bots never accept user uploads; cache writes only as a side-effect of verified fetch-by-CID.</li></ul><h2 id="operational-constraints" tabindex="-1">Operational constraints <a class="header-anchor" href="#operational-constraints" aria-label="Permalink to &quot;Operational constraints&quot;">​</a></h2><ul><li><strong>Release artifacts</strong>: GitHub Actions workflows are designed to be triggered manually (<code>workflow_dispatch</code>).</li><li><strong>Container images</strong>: backend Docker images are distroless and run as non-root.</li></ul>',7)])])}const m=o(s,[["render",r]]);export{h as __pageData,m as default};
